import React, { useState } from "react";

const Contact = ({ darkMode }) => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: ''
  });

  const [statusMessage, setStatusMessage] = React.useState('');

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setStatusMessage('Sending...');
    try {
      const response = await fetch('https://portfolio-1-ehqi.onrender.com/api/contact', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      if (response.ok) {
        setStatusMessage('Enquiry sent successfully!');
        setFormData({ name: '', email: '', message: '' });
      } else {
        const data = await response.json();
        setStatusMessage(data.error || 'Failed to send enquiry.');
      }
    } catch (error) {
      setStatusMessage('Failed to send enquiry.');
    }
  };

  return (
    <>
      <div className={`py-20 px-4 sm:px-6 md:px-8 transition-colors duration-300 ${
        darkMode ? 'bg-gray-800 text-white' : 'bg-gray-100 text-gray-900'
      }`}>
        <div className="text-center mb-12">
          <h2 className="text-3xl font-bold mb-6 font-poppins">
            Contact
          </h2>
        </div>
        <div className="max-w-4xl mx-auto flex flex-col md:flex-row md:space-x-12">
          <form onSubmit={handleSubmit} className="flex-1 mb-8 md:mb-0 space-y-4">
            <input 
              type="text" 
              name="name" 
              placeholder="Name" 
              required 
              value={formData.name} 
              onChange={handleChange} 
              className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition font-poppins" 
            />
            <input 
              type="email" 
              name="email" 
              placeholder="Email" 
              required 
              value={formData.email} 
              onChange={handleChange} 
              className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition font-poppins" 
            />
            <textarea 
              name="message" 
              placeholder="Message" 
              rows="4" 
              required 
              value={formData.message} 
              onChange={handleChange} 
              className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition font-poppins" 
            />
            <button 
              type="submit" 
              className="px-6 py-3 bg-blue-600 text-white rounded-xl hover:bg-blue-700 transition shadow-md font-poppins font-semibold"
            >
              Submit Enquiry
            </button>
            {statusMessage && (
              <p className={`mt-4 p-3 rounded-lg font-poppins ${
                statusMessage.includes('successfully') ? 'bg-green-100 text-green-800 border border-green-300 dark:bg-green-900 dark:text-green-200 dark:border-green-700' : 'bg-red-100 text-red-800 border border-red-300 dark:bg-red-900 dark:text-red-200 dark:border-red-700'
              }`}>
                {statusMessage}
              </p>
            )}
          </form>
          <div className="flex-1 text-center md:text-left space-y-4">
            <p className="font-poppins">
              <span className="font-semibold">Email:</span>{' '}
              <a href="mailto:harshwardhan0270@gmail.com" className="text-blue-600 hover:underline font-poppins">
                harshwardhan0270@gmail.com
              </a>
            </p>
            <p className="font-poppins">
              <span className="font-semibold">Phone:</span> +91 9009571862
            </p>
            <p className="font-poppins">
              <span className="font-semibold">LinkedIn:</span>{' '}
              <a href="https://www.linkedin.com/in/harshwardhan-sahu-51a673212/" className="text-blue-600 hover:underline font-poppins">
                Profile
              </a>
            </p>
          </div>
        </div>
      </div>
    </>
  );
};

export default Contact;
